CREATE OR REPLACE PROCEDURE public.sp_update_material_offering(IN p_material_product_id uuid, IN p_allow_purchase boolean, IN p_purchase_price numeric, IN p_allow_borrow boolean, IN p_rental_fee numeric, IN p_refundable_deposit numeric, IN p_default_loan_duration_days integer, IN p_max_loan_duration_days integer, IN p_is_active boolean, IN p_updated_at timestamp with time zone)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE material_offerings SET         allow_purchase = p_allow_purchase,         purchase_price = p_purchase_price,         allow_borrow = p_allow_borrow,         rental_fee = p_rental_fee,         refundable_deposit = p_refundable_deposit,         default_loan_duration_days = p_default_loan_duration_days,         max_loan_duration_days = p_max_loan_duration_days,         is_active = p_is_active,         updated_at = p_updated_at     WHERE material_product_id = p_material_product_id; END; $procedure$ ;
